fn circular_shift(x: int, shift: int) -> str:
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed.
    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "12"
    """
    def to_str(n: int) -> str:
        return str(n)
    def to_int(s: str) -> int:
        return int(s)
    def num_digits(n: int) -> int:
        return len(to_str(n))
    digits = to_str(x)
    shift = shift % num_digits(x)
    return to_str(x) if shift >= num_digits(x) else digits[-shift:] + digits[:-shift]
