fn heap_sort(iterable: [int]) -> [int]:
    fn heapify(xs: [int], n: int, i: int):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and xs[left] > xs[largest]:
            largest = left
        if right < n and xs[right] > xs[largest]:
            largest = right
        if largest != i:
            xs.swap(i, largest)
            heapify(xs, n, largest)
    var heap = iterable
    n = len(heap)
    for i in range(n // 2 - 1, -1, -1):
        heapify(heap, n, i)
    for i in range(n - 1, 0, -1):
        heap.swap(0, i)
        heapify(heap, i, 0)
    return heap
